import"./chunk-Dhz-P9mS.js";import"./chunk-s_1yO8sW.js";import"./chunk-BxnJ4ZBH.js";import"./chunk-DsFQ-TIu.js";import"./chunk-DACIzzxz.js";import"./chunk-CABSGZFi.js";import"./chunk-BkXCiOIz.js";import{C as QO,H as at,O as VO,Tt as zc,Z as dh,bt as w,dt as tP,et as jM,gt as uP,i as Ao,k as WO,m as JO,p as J,q as cP,r as Ac,wt as zO}from"./chunk-SRR2CDPr.js";import"./main-L2GBZBCH.js";import{i as G,w as e}from"./chunk-BH8BxiSD.js";var B=(()=>{let n=class n{constructor(o){this.nav=o,G({chevronBack:e})}aceptar(){this.nav.back()}};n.ɵfac=function(r){return new(r||n)(w(Ao))},n.ɵcmp=J({type:n,selectors:[[`app-terminos`]],decls:169,vars:0,consts:[[1,`ion-no-border`],[1,`barra`],[`slot`,`start`],[`defaultHref`,`/registro`,`text`,``,`icon`,`chevron-back`,`color`,`dark`],[1,`sg-page`],[1,`sg-contenido`,`aviso`],[1,`fecha-act`],[1,`nota`],[1,`ion-no-border`,`pie-aviso`],[`expand`,`block`,1,`sg-boton`,3,`click`]],template:function(r,y){r&1&&(Ac(0,`ion-header`,0)(1,`ion-toolbar`,1)(2,`ion-buttons`,2),zc(3,`ion-back-button`,3),dh(),Ac(4,`ion-title`),jM(5,`Términos y Condiciones`),dh()()(),Ac(6,`ion-content`,4)(7,`div`,5)(8,`p`,6),jM(9,`Última actualización: 17 de octubre de 2026`),dh(),Ac(10,`p`),jM(11,` Bienvenido(a) a SecretGift. Estos Términos y Condiciones («Términos») regulan el acceso y el uso de la aplicación móvil y web SecretGift («la App» o «el Servicio»), una herramienta para organizar intercambios de regalos entre amigos, familiares, estudiantes y compañeros de trabajo. Léelos con atención antes de crear tu cuenta o de unirte a un intercambio. `),dh(),Ac(12,`h3`),jM(13,`1. Aceptación de los Términos`),dh(),Ac(14,`p`),jM(15,` Al crear una cuenta, iniciar sesión, usar un link de invitación o utilizar cualquier función de la App, declaras que has leído, entendido y aceptado estos Términos y el Aviso de Privacidad. Si no estás de acuerdo con alguno de ellos, no debes usar el Servicio. `),dh(),Ac(16,`h3`),jM(17,`2. Descripción del Servicio`),dh(),Ac(18,`p`),jM(19,`SecretGift te permite, entre otras funciones:`),dh(),Ac(20,`ul`)(21,`li`),jM(22,`Crear un intercambio indicando su nombre, fecha y presupuesto por regalo.`),dh(),Ac(23,`li`),jM(24,`Invitar a otras personas mediante un link y administrar a los participantes.`),dh(),Ac(25,`li`),jM(26,`Realizar un sorteo automático que asigna a cada participante la persona a la que debe regalar.`),dh(),Ac(27,`li`),jM(28,`Consultar de forma privada la persona asignada y sus preferencias de regalo.`),dh(),Ac(29,`li`),jM(30,`Registrar tu propia lista de deseos para que quien te regale tenga una referencia.`),dh()(),Ac(31,`p`),jM(32,` SecretGift únicamente organiza la información y el sorteo. No vende regalos, no procesa pagos ni participa en la compra o entrega de ningún artículo. `),dh(),Ac(33,`h3`),jM(34,`3. Requisitos y cuenta de usuario`),dh(),Ac(35,`p`),jM(36,` Para usar la App debes crear una cuenta con tu nombre, un correo electrónico válido y una contraseña. Te comprometes a proporcionar información verdadera, completa y actualizada. Solo puedes tener una cuenta por correo electrónico. Si eres menor de edad, debes contar con el permiso de tu madre, padre o tutor para usar el Servicio. `),dh(),Ac(37,`h3`),jM(38,`4. Verificación del correo y seguridad de la cuenta`),dh(),Ac(39,`ul`)(40,`li`),jM(41,` Para activar tu cuenta te enviaremos un código de 6 dígitos a tu correo. El código vence a los 10 minutos y tiene un número limitado de intentos. `),dh(),Ac(42,`li`),jM(43,` Tu contraseña es personal. Debes mantenerla en secreto y no compartirla. Nosotros nunca te la pediremos por correo ni por mensaje. `),dh(),Ac(44,`li`),jM(45,` Eres responsable de todo lo que ocurra desde tu cuenta. Si sospechas que alguien más accedió a ella, cambia tu contraseña de inmediato desde la opción «¿Olvidaste tu contraseña?». `),dh(),Ac(46,`li`),jM(47,`Tus contraseñas se almacenan de forma cifrada; nadie del equipo puede verlas.`),dh()(),Ac(48,`h3`),jM(49,`5. Creación y organización de intercambios`),dh(),Ac(50,`p`),jM(51,`La persona que crea un intercambio es su organizador y es responsable de:`),dh(),Ac(52,`ul`)(53,`li`),jM(54,`Indicar una fecha y un presupuesto reales y comunicarlos con claridad a los participantes.`),dh(),Ac(55,`li`),jM(56,`Invitar únicamente a personas que deseen participar.`),dh(),Ac(57,`li`),jM(58,`Revisar la lista de participantes antes de realizar el sorteo.`),dh()(),Ac(59,`p`),jM(60,` El organizador puede quitar participantes mientras el sorteo no se haya realizado. Una vez hecho el sorteo, la lista ya no puede modificarse. `),dh(),Ac(61,`h3`),jM(62,`6. Invitaciones y participantes`),dh(),Ac(63,`ul`)(64,`li`),jM(65,` Cada intercambio tiene un link de invitación único. Cualquier persona que reciba ese link podrá ver los datos básicos del intercambio (nombre, fecha, presupuesto, organizador y número de participantes) y, si tiene cuenta, unirse a él. `),dh(),Ac(66,`li`),jM(67,` Comparte el link solo con las personas que quieras invitar. SecretGift no puede saber quién recibió el link a través de otros medios, como WhatsApp o redes sociales. `),dh(),Ac(68,`li`),jM(69,` Si una persona no tiene cuenta, deberá crear una y verificar su correo para poder unirse. `),dh(),Ac(70,`li`),jM(71,` Cuando se realiza el sorteo, o cuando pasa la fecha del intercambio, el link deja de aceptar nuevos participantes. `),dh(),Ac(72,`li`),jM(73,`Un intercambio puede tener un máximo de 30 participantes.`),dh()(),Ac(74,`h3`),jM(75,`7. Sorteo y asignaciones`),dh(),Ac(76,`ul`)(77,`li`),jM(78,` El sorteo se realiza de manera automática y aleatoria desde el servidor, cuando el organizador lo solicita y hay al menos 3 participantes. `),dh(),Ac(79,`li`),jM(80,`El sistema valida que ninguna persona sea asignada a sí misma y que cada participante reciba exactamente un regalo.`),dh(),Ac(81,`li`),jM(82,`El sorteo es definitivo y no puede repetirse ni deshacerse.`),dh(),Ac(83,`li`),jM(84,` Cada participante solo puede consultar a la persona que le tocó. Ni el organizador ni nadie más pueden ver las asignaciones de los demás. `),dh(),Ac(85,`li`),jM(86,` Te pedimos mantener en secreto la persona que te tocó. Revelarla a otros participantes es decisión y responsabilidad tuya. `),dh()(),Ac(87,`h3`),jM(88,`8. Lista de deseos y contenido del usuario`),dh(),Ac(89,`p`),jM(90,` Puedes registrar hasta 10 preferencias de regalo. Esa lista será visible únicamente para la persona que te haya tocado en el sorteo. Eres responsable del contenido que escribas, que debe ser respetuoso y no contener información de terceros ni datos sensibles. Nos reservamos el derecho de eliminar contenido que incumpla estos Términos. `),dh(),Ac(91,`h3`),jM(92,`9. Uso aceptable`),dh(),Ac(93,`p`),jM(94,`Al usar SecretGift te comprometes a no:`),dh(),Ac(95,`ul`)(96,`li`),jM(97,`Usar el Servicio para fines ilegales, fraudulentos o engañosos.`),dh(),Ac(98,`li`),jM(99,`Crear cuentas con datos falsos o suplantar la identidad de otra persona.`),dh(),Ac(100,`li`),jM(101,`Agregar o invitar a personas a un intercambio sin que lo sepan o lo deseen, ni usar el Servicio para acosar o enviar spam.`),dh(),Ac(102,`li`),jM(103,`Intentar acceder a cuentas, intercambios o asignaciones de otras personas.`),dh(),Ac(104,`li`),jM(105,`Probar, vulnerar, sobrecargar o interferir con la seguridad o el funcionamiento de la App o del servidor.`),dh(),Ac(106,`li`),jM(107,`Usar programas automáticos para registrarte, adivinar códigos o contraseñas, o extraer información.`),dh(),Ac(108,`li`),jM(109,`Copiar, modificar, descompilar o distribuir el Servicio sin autorización.`),dh()(),Ac(110,`h3`),jM(111,`10. Privacidad y protección de datos`),dh(),Ac(112,`p`),jM(113,` El tratamiento de tus datos personales se rige por nuestro Aviso de Privacidad. En resumen, recopilamos tu nombre, correo electrónico, la información de tus intercambios y tus preferencias de regalo para crear y gestionar los intercambios, realizar el sorteo y mostrarte la información de forma privada y segura. No vendemos ni compartimos tus datos con terceros sin tu consentimiento, salvo que una autoridad competente lo exija. `),dh(),Ac(114,`h3`),jM(115,`11. Eliminación y suspensión de cuentas`),dh(),Ac(116,`ul`)(117,`li`),jM(118,` Puedes eliminar tu cuenta en cualquier momento desde `),Ac(119,`b`),jM(120,`Perfil → Eliminar cuenta`),dh(),jM(121,`, confirmando con tu contraseña. `),dh(),Ac(122,`li`),jM(123,` Al eliminarla, tu cuenta pasa a estado `),Ac(124,`b`),jM(125,`inactivo`),dh(),jM(126,`: ya no podrás iniciar sesión y tus datos se conservan durante `),Ac(127,`b`),jM(128,`30 días`),dh(),jM(129,` por motivos de seguridad. Transcurrido ese plazo, se eliminan de forma definitiva. `),dh(),Ac(130,`li`),jM(131,` Si organizas un intercambio cuya fecha aún no pasa, deberás esperar a que termine para poder eliminar tu cuenta. `),dh(),Ac(132,`li`),jM(133,` En los intercambios de otras personas en los que participabas, tu nombre se sustituirá por «Cuenta eliminada» para no afectar el sorteo de los demás. `),dh(),Ac(134,`li`),jM(135,` Podemos suspender o cancelar una cuenta que incumpla estos Términos, que ponga en riesgo la seguridad del Servicio o que se use de forma abusiva. `),dh()(),Ac(136,`h3`),jM(137,`12. Regalos, acuerdos y responsabilidad entre participantes`),dh(),Ac(138,`p`),jM(139,` Los intercambios son acuerdos entre los propios participantes. SecretGift no interviene en la compra, el pago, el envío, la entrega ni la calidad de los regalos, ni garantiza que todos los participantes cumplan con el presupuesto, la fecha o su compromiso de regalar. Cualquier desacuerdo debe resolverse directamente entre los participantes y el organizador. `),dh(),Ac(140,`h3`),jM(141,`13. Disponibilidad del Servicio`),dh(),Ac(142,`p`),jM(143,` Hacemos nuestro mejor esfuerzo para que la App funcione de manera continua, pero no garantizamos que esté libre de errores, interrupciones o pérdidas de información. Podemos realizar mantenimientos, mejoras o cambios en cualquier momento, y algunas funciones pueden modificarse o dejar de estar disponibles. El Servicio se proporciona «tal cual» y «según disponibilidad». `),dh(),Ac(144,`h3`),jM(145,`14. Propiedad intelectual`),dh(),Ac(146,`p`),jM(147,` El nombre SecretGift, su diseño, logotipos, textos, código y demás elementos de la App son propiedad de sus desarrolladores y están protegidos por las leyes aplicables. Estos Términos solo te otorgan una licencia personal, limitada, revocable y no exclusiva para usar la App conforme a su finalidad. El contenido que tú escribes (como tus preferencias de regalo) sigue siendo tuyo; nos autorizas únicamente a almacenarlo y mostrarlo para prestarte el Servicio. `),dh(),Ac(148,`h3`),jM(149,`15. Limitación de responsabilidad`),dh(),Ac(150,`p`),jM(151,` En la medida permitida por la ley, SecretGift y sus desarrolladores no serán responsables por daños indirectos, incidentales o consecuentes derivados del uso o de la imposibilidad de uso de la App, incluyendo, sin limitarse a ello, regalos no entregados, desacuerdos entre participantes, pérdida de datos, accesos no autorizados causados por descuido del usuario (por ejemplo, compartir su contraseña) o fallas de servicios de terceros como el correo electrónico o la conexión a internet. `),dh(),Ac(152,`h3`),jM(153,`16. Modificaciones a los Términos`),dh(),Ac(154,`p`),jM(155,` Podemos actualizar estos Términos para reflejar cambios en la App o en la ley. Publicaremos la versión vigente en la App con su fecha de actualización. Si continúas usando el Servicio después de un cambio, se entenderá que lo aceptas. Si no estás de acuerdo con la nueva versión, puedes eliminar tu cuenta. `),dh(),Ac(156,`h3`),jM(157,`17. Ley aplicable y jurisdicción`),dh(),Ac(158,`p`),jM(159,` Estos Términos se interpretan conforme a las leyes de los Estados Unidos Mexicanos. Para cualquier controversia relacionada con el Servicio, las partes se someten a los tribunales competentes del estado de Aguascalientes, renunciando a cualquier otro fuero que pudiera corresponderles por su domicilio presente o futuro. `),dh(),Ac(160,`h3`),jM(161,`18. Contacto`),dh(),Ac(162,`p`),jM(163,` Si tienes dudas, comentarios o solicitudes sobre estos Términos, sobre tus datos o sobre tu cuenta, comunícate con el equipo de SecretGift, proyecto desarrollado en la Universidad Tecnológica de Aguascalientes. `),dh(),Ac(164,`p`,7),jM(165,` Al presionar «Entendido» confirmas que leíste estos Términos y Condiciones. `),dh()()(),Ac(166,`ion-footer`,8)(167,`ion-button`,9),at(`click`,function(){return y.aceptar()}),jM(168,`Entendido`),dh()())},dependencies:[QO,tP,uP,cP,WO,VO,zO,JO],styles:[`.barra[_ngcontent-%COMP%]{--%NS%background: #f6faff;--%NS%color: var(--%NS%sg-texto)}.barra[_ngcontent-%COMP%]   ion-title[_ngcontent-%COMP%]{font-size:16px;font-weight:600}.aviso[_ngcontent-%COMP%]{font-size:13.5px;line-height:1.55}.aviso[_ngcontent-%COMP%]   p[_ngcontent-%COMP%]{margin:0 0 14px}.aviso[_ngcontent-%COMP%]   h3[_ngcontent-%COMP%]{font-size:14.5px;font-weight:600;margin:18px 0 6px}.aviso[_ngcontent-%COMP%]   ul[_ngcontent-%COMP%]{margin:0 0 8px;padding-left:20px}.aviso[_ngcontent-%COMP%]   ul[_ngcontent-%COMP%]   li[_ngcontent-%COMP%]{margin-bottom:4px}.aviso[_ngcontent-%COMP%]   .nota[_ngcontent-%COMP%]{color:var(--%NS%sg-texto-suave);font-size:12.5px}.pie-aviso[_ngcontent-%COMP%]{background:#e3eefc;padding:10px 22px calc(14px + var(--%NS%sg-bottom))}.pie-aviso[_ngcontent-%COMP%]   .sg-boton[_ngcontent-%COMP%]{max-width:420px;margin:0 auto}.fecha-act[_ngcontent-%COMP%]{font-size:12px;color:var(--%NS%sg-texto-suave);margin:0 0 12px}.aviso[_ngcontent-%COMP%]   b[_ngcontent-%COMP%]{font-weight:600}.aviso[_ngcontent-%COMP%]   li[_ngcontent-%COMP%]{margin-bottom:6px}`]});return n})();export{B as TerminosPage};